from .requests import Client


class ProxyMngrAdministrative(Client):

    def __init__(self, hostname, *args, **kwargs):
        super().__init__(hostname, *args, **kwargs)
        self.base_url = f"{self._generate_url()}/"

    def get_proxy_mngr_welcome_msg(self):
        """
        '/' - Get UE proxy mngr upgrade server welcome message

        :return:
        """
        return self._get_from_server(url=self.base_url)


class ProxyMngrStorage(Client):

    def __init__(self, hostname, remote_endpoint='releases', *args, **kwargs):
        super().__init__(hostname, *args, **kwargs)
        self.base_url = f"{self._generate_url()}/{remote_endpoint}"

    # --------------------------------- GET ---------------------------------------------------
    def get_ue_proxy_releases(self):
        """
        /releases/ - get all releases of ueproxy from UE PC
        :return:
        """
        return self._get_from_server(url=self.base_url)

    def get_autoupdate_status(self):
        """
        /releases/autoupdate - get autoupdate status
        :return bool: True when activated, False otherwise
        """
        return self._get_from_server(url=f"{self.base_url}/autoupdate")

    # --------------------------------- POST --------------------------------------------------
    def download_ueproxy_release(self, ueproxy_ver, python_ver, os_name, os_ver, file_extension, ue_type):
        """
        /releases/download - download specified ueproxy release from artifactory and save on UE PC

        :param str ueproxy_ver:
        :param str python_ver:
        :param str os_name:
        :param str os_ver:
        :param str file_extension:
        :param str ue_type:
        :return bool response: True if release is deleted or raise HTTP_404_NOT_FOUND
        """
        json = {'ver': ueproxy_ver, 'python_ver': python_ver, 'os_name': os_name, 'os_ver': os_ver,
                'rel_format': file_extension, 'ue_type': ue_type}
        headers = {'accept': 'application/json', 'Content-Type': 'application/json'}
        return self._post_to_server(url=f"{self.base_url}/download", json=json, headers=headers)

    def update_proxy_mngr_artifactory(self, proxy_mngr_artifactory):
        json = {'proxy_mngr_artifactory': proxy_mngr_artifactory}
        headers = {'accept': 'application/json', 'Content-Type': 'application/json'}
        try:
            return self._post_to_server(url=f"{self.base_url}/proxy_mngr_artifactory", json=json, headers=headers)
        except Exception:
            pass

    def download_latest_ueproxy_release(self, ue_type, file_extension):
        """
        /releases/download/latest - download latest ueproxy release from artifactory and save on UE PC

        :param ue_type: ueproxy release package ue type (e.g. 'android', 'iphone')
        :param file_extension: ueproxy release package extension
        :return: downloaded package name or empty string if failed
        """
        json = {'ue_type': ue_type, 'rel_format': file_extension}
        headers = {'accept': 'application/json', 'Content-Type': 'application/json'}
        return self._post_to_server(url=f"{self.base_url}/download/latest", json=json, headers=headers)

    # --------------------------------- DELETE ------------------------------------------------
    def delete_ueproxy_release(self, ueproxy_ver, python_ver, os_name, ue_type, os_ver, file_extension):
        """
        /releases/delete - delete specified ueproxy release from UE PC

        :param str ueproxy_ver:
        :param str python_ver:
        :param str os_name:
        :param str ue_type:
        :param str os_ver:
        :param str file_extension:
        :return bool response: True if release is deleted or raise HTTP_404_NOT_FOUND
        """
        json = {'ver': ueproxy_ver, 'python_ver': python_ver, 'os_name': os_name, 'os_ver': os_ver,
                'rel_format': file_extension, 'ue_type': ue_type}
        headers = {'accept': 'application/json', 'Content-Type': 'application/json'}
        return self._delete_from_server(url=f"{self.base_url}/delete", json=json, headers=headers)


class ProxyMngrExecution(Client):

    def __init__(self, hostname, remote_endpoint='services', *args, **kwargs):
        super().__init__(hostname, *args, **kwargs)
        self.base_url = f"{self._generate_url()}/{remote_endpoint}"

    # --------------------------------- GET ---------------------------------------------------
    def get_ueproxy_running_services(self):
        """
        /services/ - get all running services of ueproxy from UE PC
        :return dict: request response - example {
                                                   "8181": {
                                                     "service_ver": '1.8.0',
                                                     "access_layer": {
                                                         "name": "taf.ue.proxy.access.iphone",
                                                         "ver": "1.8.0"
                                                        }
                                                     }
                                                 }
        """
        return self._get_from_server(url=self.base_url)

    def get_service_logs(self, ue_type, port, request_timeout=None):
        """
        /services/logs - get service logs (proxy manager logs + ueproxy service execution logs).

        :param ue_type: Type of Ue which was used during the test
        :param port: Port number on which ueproxy service used in test has been deployed
        :param request_timeout: Timeout for request
        :return FileResponse: Zipped log files
        """
        params = {'ue_type': ue_type, 'port': port}
        response = self._get_from_server(url=f"{self.base_url}/logs", params=params, timeout=request_timeout)
        return response

    # --------------------------------- POST --------------------------------------------------
    def start_ueproxy_service(self, ueproxy_ver, python_ver, os_name, ue_type, os_ver, release_format):
        """
        /services/start - start ueproxy server as service at UE PC on specific port.

        :param str ueproxy_ver:
        :param str python_ver:
        :param str os_name:
        :param str ue_type: Type of UE which will be used in test
        :param str os_ver:
        :param str release_format:
        :return dict: request response - example {'service': {'pid': 9780,
                                                             'release': 'ueproxy-1.4.0-py38-win_0.9.0.pyz',
                                                             'url': 'http://127.0.0.1:8080'},
                                                             'access_layer': 'taf.ue.proxy.access.android;ver.1.9.0',
                                                             'bootup_duration': 1.5834665298461914,
                                                             'start_time': '2023-03-06T10:28:27.064132',
                                                             'logs': ['proxy.service.raw.log',
                                                                      'proxy.log',
                                                                      'proxy.debug.log']}
        """
        json = {'ver': ueproxy_ver, 'python_ver': python_ver, 'os_name': os_name, 'ue_type': ue_type, 'os_ver': os_ver,
                'rel_format': release_format}
        return self._post_to_server(url=f"{self.base_url}/start", json=json)

    def stop_service(self, port):
        """
        /services/stop - stop service running at UE PC

        :param int port: UEPC port where ueproxy was deployed
        :return bool response: True if service is stopped or False
        """
        json = {'port': port}
        return self._post_to_server(url=f"{self.base_url}/stop", json=json)

    def release_ueproxy_service(self, port):
        """
        /services/release - mark ueproxy service as inactive

        :param port: UEPC port where ueproxy was deployed
        """
        json = {'port': port}
        return self._post_to_server(url=f"{self.base_url}/release", json=json)
